{"path":"workflow.py","content":""""Order reconciliation (spec v1).

Pure functions only: no file, network or process access.
Amounts are handled as decimal strings and converted to integer cents
without using binary floating point.
"""

import csv
import json
import re
from decimal import Decimal, InvalidOperation

_AMOUNT_RE = re.compile(r"^\d{1,14}(\.\d{1,2})?$")

_ORDER_HEADER = ["order_id", "customer", "amount", "status", "created_at"]
_REFUND_HEADER = ["refund_id", "order_id", "amount"]


def _parse_amount_cents(raw, what):
    """Return integer cents for a non-negative decimal string (<= 2 dp)."""
    if raw is None:
        raise ValueError("%s: missing amount" % what)
    text = str(raw).strip()
    if text == "":
        raise ValueError("%s: empty amount" % what)
    if not _AMOUNT_RE.match(text):
        # Rejects NaN, Infinity, negatives, >2 decimals and exotic notation.
        raise ValueError("%s: invalid amount %r" % (what, raw))
    try:
        value = Decimal(text)
    except InvalidOperation:
        raise ValueError("%s: invalid amount %r" % (what, raw))
    if not value.is_finite():
        raise ValueError("%s: non-finite amount %r" % (what, raw))
    if value < 0:
        raise ValueError("%s: negative amount %r" % (what, raw))
    if value != value.quantize(Decimal("0.01")):
        raise ValueError("%s: more than two decimals %r" % (what, raw))
    return int(value.scaleb(2).to_integral_value())


def _read_rows(csv_text, expected_header, what):
    """Return list of dicts for a CSV string, validating the header."""
    if csv_text is None:
        raise ValueError("%s: input must be a string" % what)
    text = csv_text
    if text.startswith("\ufeff"):
        text = text[1:]
    reader = csv.reader(text.splitlines())
    rows = []
    header = None
    for line in reader:
        if not line or all((cell is None or cell.strip() == "") for cell in line):
            continue
        if header is None:
            header = [cell.strip() for cell in line]
            if header != expected_header:
                raise ValueError(
                    "%s: expected header %s, got %s" % (what, expected_header, header)
                )
            continue
        if len(line) != len(expected_header):
            raise ValueError("%s: row has %d fields, expected %d" % (what, len(line), len(expected_header)))
        rows.append(dict(zip(expected_header, (cell.strip() for cell in line))))
    if header is None:
        raise ValueError("%s: header row is required" % what)
    return rows


def _key_signature(row, fields):
    return tuple(row.get(field, "") for field in fields)


def reconcile(orders_csv, refunds_csv, policy="v1", cutoff=None):
    """Reconcile orders against refunds according to the v1 contract.

    Returns a dict with ``orders`` (sorted by order_id), ``customers``
    (sorted by customer) and ``totals``; all money values are integer cents.
    """
    if policy != "v1":
        raise ValueError("unsupported policy %r" % (policy,))
    # cutoff is not part of the v1 semantics; accepted for forward compatibility.
    del cutoff

    order_fields = _ORDER_HEADER
    refund_fields = _REFUND_HEADER

    # ---- orders: deduplicate by order_id -------------------------------
    orders = {}            # order_id -> record
    order_rows = _read_rows(orders_csv, order_fields, "orders")
    for row in order_rows:
        order_id = row["order_id"]
        if order_id == "":
            raise ValueError("orders: order_id is required")
        customer = row["customer"]
        if customer == "":
            raise ValueError("orders: customer is required for order %s" % order_id)
        status = row["status"]
        if status not in ("paid", "cancelled"):
            raise ValueError("orders: unknown status %r for order %s" % (status, order_id))
        paid_cents = _parse_amount_cents(row["amount"], "orders %s amount" % order_id)
        record = {
            "order_id": order_id,
            "customer": customer,
            "status": status,
            "paid_cents": paid_cents,
            "created_at": row["created_at"],
        }
        existing = orders.get(order_id)
        if existing is not None:
            if _key_signature(existing, order_fields) != _key_signature(record, order_fields):
                raise ValueError("orders: conflicting rows for order_id %s" % order_id)
            continue
        orders[order_id] = record

    # ---- refunds: deduplicate by refund_id -----------------------------
    refunds = {}           # refund_id -> record
    refund_rows = _read_rows(refunds_csv, refund_fields, "refunds")
    for row in refund_rows:
        refund_id = row["refund_id"]
        if refund_id == "":
            raise ValueError("refunds: refund_id is required")
        order_id = row["order_id"]
        refund_cents = _parse_amount_cents(row["amount"], "refunds %s amount" % refund_id)
        record = {
            "refund_id": refund_id,
            "order_id": order_id,
            "amount_cents": refund_cents,
        }
        existing = refunds.get(refund_id)
        if existing is not None:
            if _key_signature(existing, refund_fields) != _key_signature(record, refund_fields):
                raise ValueError("refunds: conflicting rows for refund_id %s" % refund_id)
            continue
        refunds[refund_id] = record

    # ---- validate refunds against orders -------------------------------
    refund_by_order = {}
    for refund_id in sorted(refunds):
        record = refunds[refund_id]
        order = orders.get(record["order_id"])
        if order is None:
            raise ValueError("refunds: unknown order %s for refund %s" % (record["order_id"], refund_id))
        if order["status"] != "paid":
            raise ValueError("refunds: order %s is not paid (refund %s)" % (order["order_id"], refund_id))
        refund_by_order.setdefault(record["order_id"], 0)
        refund_by_order[record["order_id"]] += record["amount_cents"]
        paid_cents = order["paid_cents"]
        if refund_by_order[record["order_id"]] > paid_cents:
            raise ValueError(
                "refunds: refund total %d exceeds paid %d for order %s"
                % (refund_by_order[record["order_id"]], paid_cents, order["order_id"])
            )

    # ---- build result ---------------------------------------------------
    result_orders = []
    totals_paid = 0
    totals_refund = 0
    for order_id in sorted(orders):
        order = orders[order_id]
        if order["status"] != "paid":
            continue
        paid_cents = order["paid_cents"]
        refund_cents = refund_by_order.get(order_id, 0)
        net_cents = paid_cents - refund_cents
        result_orders.append(
            {
                "order_id": order_id,
                "customer": order["customer"],
                "paid_cents": paid_cents,
                "refund_cents": refund_cents,
                "net_cents": net_cents,
            }
        )
        totals_paid += paid_cents
        totals_refund += refund_cents

    customer_totals = {}
    for item in result_orders:
        customer_totals[item["customer"]] = customer_totals.get(item["customer"], 0) + item["net_cents"]

    customers = [
        {"customer": name, "net_cents": customer_totals[name]}
        for name in sorted(customer_totals)
    ]

    return {
        "orders": result_orders,
        "customers": customers,
        "totals": {
            "paid_cents": totals_paid,
            "refund_cents": totals_refund,
            "net_cents": totals_paid - totals_refund,
        },
    }


def export_bundle(result):
    """Serialize a reconcile result into a simple in-memory bundle."""
    if not isinstance(result, dict):
        raise ValueError("result must be a dict")
    summary = {
        "totals": result.get("totals", {"paid_cents": 0, "refund_cents": 0, "net_cents": 0}),
        "order_count": len(result.get("orders", [])),
        "customer_count": len(result.get("customers", [])),
    }
    return {
        "summary.json": json.dumps(summary, sort_keys=True),
        "orders.json": json.dumps(result.get("orders", []), sort_keys=True),
        "customers.json": json.dumps(result.get("customers", []), sort_keys=True),
    }
"}

